select (select max(financialid)+1 from set_financialheader) + ROW_NUMBER() OVER (ORDER BY t.Description ASC) as FinancialID , t.Description FinancialName, convert(bit,0) NewPage, 'D' as ElementType, 'L' as Alignment, convert(bit,0) Bold , @FinancialHeaderID as ElementSequence, t.Description ElementName, '' as NoteNo, convert(bit,0) ExpectedResultInDb, convert(bit,0) DataIn, convert(bit,1) FixedInput, t.Amount, convert(bit,0) DataToBeCollected, null as Formula, '000' FinancialCode, 0 as Segment, @AccountCodeFrom as COACodeFrom , @AccountCodeTo as COACodeTo, '' AS Action, 2 as OrderBy from ( select finaltab.Description,sum(finaltab.DebitAmount) - sum(finaltab.CreditAmount) Amount from ( select * from ( select FinTAB.CodeCombinationID,FinTAB.DocumentNo , FinTAB.DocumentDate ,UPPER(FinTAB.Narration) AS Narration ,case when FinTAB.Amount > 0 then FinTAB.Amount else 0 end as DebitAmount, case when FinTAB.Amount < 0 then abs(FinTAB.Amount) else 0 end as CreditAmount ,UPPER(FinTAB.TransactionType) AS TransactionType,UPPER(FinTAB.Description) AS Description,UPPER(FinTAB.CodeDescription) AS CodeDescription,UPPER(FinTAB.DocumentType) AS DocumentType ,UPPER(FinTAB.CostCenter) AS CostCenter,FinTAB.SerialNo,null as CreateDate,OperatingUnitName ,'' AS NarrationHeader,0 as DocumentTypeID from (
SELECT GL_TransactionDetail.CodeCombinationID, '' as DocumentNo, @FromDate as DocumentDate, 'Opening Balance' as Narration, case when @isCurrentYearActivity = 1 then 0 Else (ISNULL(SUM(CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN GL_TransactionDetail.Amount ELSE 0 END), 0) - ISNULL(SUM(CASE WHEN GL_TransactionDetail.TransactionType = 'Credit' THEN GL_TransactionDetail.Amount ELSE 0 END), 0)) End AS Amount, '' as TransactionType, GL_CodeCombinationDetail.Description , GL_CodeCombinationDetail.Description + '-' + SET_OperatingUnit.OperatingUnitName as CodeDescription, '' as DocumentType, --Set_CostCenter.CostCenterName As CostCenter, '' As CostCenter, 0 As SerialNo,SET_OperatingUnit.OperatingUnitName FROM GL_TransactionDetail INNER JOIN GL_TransactionHeader ON GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.Status = 1 INNER JOIN GL_CodeCombinationDetail ON --GL_CodeCombinationDetail.CompanyID = GL_TransactionDetail.CompanyID AND GL_CodeCombinationDetail.ChartOfAccountID = GL_TransactionDetail.ChartOfAccountID AND GL_CodeCombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionHeader.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID LEFT JOIN Set_CostCenter ON Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join SET_Company on SET_Company.CompanyId = GL_TransactionHeader.CompanyID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = SET_Company.OperatingUnitId {1} WHERE GL_TransactionDetail.CompanyID in @CompanyID AND GL_TransactionDetail.PeriodID = @PeriodID AND GL_TransactionDetail.ChartOfAccountID = @ChartOfAccountID AND GL_TransactionDetail.Status = 1 AND GL_TransactionHeader.DocumentDate < @FromDate {AccountCodeFilter} {0} And GL_TransactionHeader.StatusCode = 1 GROUP BY GL_TransactionDetail.CodeCombinationID, GL_CodeCombinationDetail.Description,SET_OperatingUnit.OperatingUnitName )as FinTAB --{2} union all select * from ( SELECT distinct GL_TransactionDetail.CodeCombinationID, GL_TransactionHeader.DocumentNo, GL_TransactionHeader.DocumentDate, GL_TransactionDetail.Narration, CASE WHEN GL_TransactionDetail.TransactionType = 'Debit' THEN GL_TransactionDetail.Amount ELSE 0 END AS DebitAmount, CASE WHEN GL_TransactionDetail.TransactionType = 'Credit' THEN GL_TransactionDetail.Amount ELSE 0 END AS CreditAmount, GL_TransactionDetail.TransactionType, GL_CodeCombinationDetail.Description , GL_CodeCombinationDetail.Description + '-' + SET_OperatingUnit.OperatingUnitName as CodeDescription, SET_DocumentType.DocumentType, Set_CostCenter.CostCenterName As CostCenter, GL_TransactionDetail.SerialNo , GL_TransactionHeader.CreateDate,OperatingUnitName ,GL_TransactionHeader.Narration AS NarrationHeader,GL_TransactionHeader.DocumentTypeID FROM GL_TransactionDetail INNER JOIN GL_TransactionHeader ON GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.Status = 1 INNER JOIN GL_CodeCombinationDetail ON --GL_CodeCombinationDetail.CompanyID = GL_TransactionDetail.CompanyID AND GL_CodeCombinationDetail.ChartOfAccountID = GL_TransactionDetail.ChartOfAccountID AND GL_CodeCombinationDetail.CodeCombinationID = GL_TransactionDetail.CodeCombinationID INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = GL_TransactionDetail.CompanyID AND SET_DocumentType.PeriodID = GL_TransactionDetail.PeriodID AND SET_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID LEFT JOIN Set_CostCenter ON Set_CostCenter.CostCenterID = GL_TransactionDetail.CostCenterID inner join SET_Company on SET_Company.CompanyId = GL_TransactionHeader.CompanyID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = SET_Company.OperatingUnitId {1} WHERE GL_TransactionDetail.CompanyID in @CompanyID AND GL_TransactionDetail.PeriodID = @PeriodID AND GL_TransactionDetail.ChartOfAccountID = @ChartOfAccountID AND GL_TransactionDetail.Status = 1 AND GL_TransactionHeader.StatusCode = 1 AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate AND GL_TransactionHeader.TransactionID not in ( select GL_TransactionHeader.TransactionID from GL_TransactionHeader INNER JOIN SET_DocumentType ON GL_TransactionHeader.CompanyID = SET_DocumentType.CompanyID AND GL_TransactionHeader.PeriodID = SET_DocumentType.PeriodID AND GL_TransactionHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID where DocumentType LIKE 'GL-OPENING' + '%' AND GL_TransactionHeader.DocumentDate BETWEEN @FromDate AND @ToDate ) {AccountCodeFilter} {0} And GL_TransactionHeader.StatusCode = 1 Group By GL_TransactionHeader.DocumentNo, GL_TransactionDetail.CodeCombinationID, GL_TransactionHeader.DocumentDate, GL_TransactionDetail.Narration, GL_TransactionDetail.Amount, GL_TransactionDetail.TransactionType, GL_CodeCombinationDetail.Description, SET_DocumentType.DocumentType, GL_TransactionDetail.SerialNo, Set_CostCenter.CostCenterName,GL_TransactionDetail.SerialNo,GL_TransactionHeader.CreateDate,OperatingUnitName ,GL_TransactionHeader.Narration,GL_TransactionHeader.DocumentTypeID ) as FinTAB {2} {3}
) as tab ) as FinalTAB group by finaltab.Description )t where t.Amount<>0
